<section class="panel inset"><h2>Публичный профиль OSS</h2>
<p>Публикуются только явно указанные тексты, даты публичных вех и проверенные release notes. Убедитесь, что upstream и эти сведения предназначены для публичного доступа.</p>
<form method="post" class="formgrid"><?php formFields('oss.settings') ?><input type="hidden" name="project_id" value="<?= $pid ?>"><input type="hidden" name="version" value="<?= (int)($cfg['version']??0) ?>">
<label>Slug<input name="slug" required pattern="[a-z0-9][a-z0-9-]{1,78}[a-z0-9]" maxlength="80" value="<?= h($cfg['slug']??'') ?>" <?= $cfg?'readonly':'' ?>></label>
<label>Upstream GitHub (owner/repository)<input name="upstream" required maxlength="140" value="<?= h($cfg['upstream']??'') ?>" <?= $cfg?'readonly':'' ?>></label>
<label>Публичное название<input name="public_title" maxlength="180" required value="<?= h($cfg['public_title']??'') ?>"></label>
<label>Публичное описание<textarea name="description" maxlength="4000" required><?= h($cfg['description']??'') ?></textarea></label>
<label>Доступ<select name="published"><?php selectOptions(['0'=>'Закрыт','1'=>'Опубликован'],$cfg['published']??0) ?></select></label><button class="primary">Сохранить профиль</button></form>
<?php if ($cfg && $cfg['published']): ?><p><a href="<?= h(url('oss.public',['slug'=>$cfg['slug']])) ?>">Открыть публичную витрину</a></p><?php endif ?></section>
<?php if (!$cfg) return; ?>
<section class="panel inset"><h2>Внешние contributors</h2><p>Код одноразовый, действует 1–168 часов. Доступ действует до 30 дней, сессия — 30 минут бездействия. Код не подтверждает личность GitHub; проверяйте её отдельно. Повторная выдача отзывает старую сессию.</p>
<?php if (!empty($inviteToken)): ?><div role="status" class="notice"><label>Передайте код защищённым каналом<input readonly value="<?= h($inviteToken) ?>"></label><a href="<?= h(url('oss.join')) ?>">Адрес входа contributor</a></div><?php endif ?>
<form method="post" class="formgrid"><?php formFields('oss.invite') ?><input type="hidden" name="project_id" value="<?= $pid ?>"><label>Псевдоним<input name="display_name" maxlength="120" required></label><label>Срок, часов<input name="hours" type="number" min="1" max="168" value="24" required></label><button class="primary">Выдать код</button></form>
<?php foreach ($contributors as $c): ?><div class="splitrow"><div><b><?= h($c['display_name']) ?></b><small><?= $c['revoked_at']?'Отозван':($c['accepted_at']?($c['access_until']>time()?'Активен':'Истёк'):($c['expires_at']>time()?'Ожидает входа':'Код истёк')) ?></small></div>
<?php if (!$c['revoked_at']): ?><form method="post"><?php formFields('oss.revoke') ?><input type="hidden" name="project_id" value="<?= $pid ?>"><input type="hidden" name="contributor_id" value="<?= (int)$c['id'] ?>"><button class="secondary compact">Отозвать</button></form><?php endif ?>
<form method="post"><?php formFields('oss.reissue') ?><input type="hidden" name="project_id" value="<?= $pid ?>"><input type="hidden" name="contributor_id" value="<?= (int)$c['id'] ?>"><input type="hidden" name="hours" value="24"><button class="secondary compact">Новый код (24 ч)</button></form></div><?php endforeach ?></section>
<section class="panel inset"><h2>Очередь triage</h2><form method="get" class="inline"><input type="hidden" name="p" value="oss"><input type="hidden" name="project" value="<?= $pid ?>"><label>Статус<select name="state"><?php selectOptions([''=>'Все']+OSS_STATES,$state) ?></select></label><button class="secondary">Фильтровать</button></form>
<?php if (!$queue): ?><p>Нет вкладов.</p><?php endif ?>
<?php foreach ($queue as $q): ?><div class="splitrow"><div><a href="<?= h(url('oss',['project'=>$pid,'id'=>$q['id'],'state'=>$state,'n'=>$page])) ?>">#<?= (int)$q['id'] ?> <?= h($q['title']) ?></a><small><?= h($q['display_name']) ?> · <?= h(OSS_STATES[$q['state']]) ?></small></div><a href="<?= h($q['upstream_url']) ?>" rel="noopener noreferrer">Upstream</a></div><?php endforeach ?>
<?php if ($selected): ?><article class="panel inset"><h3>#<?= (int)$selected['id'] ?> <?= h($selected['title']) ?></h3><p class="criteria-text"><?= h($selected['body']) ?></p><p><?= h(OSS_STATES[$selected['state']]) ?> · <a href="<?= h($selected['upstream_url']) ?>" rel="noopener noreferrer">Upstream</a></p>
<?php if ($selected['task_id']): ?><p><a href="<?= h(url('task',['id'=>$selected['task_id']])) ?>">Связанная задача</a></p><?php endif ?>
<?php if (in_array($selected['state'],['new','reviewing'],true)): ?><form method="post" class="formgrid"><?php formFields('oss.triage') ?><input type="hidden" name="project_id" value="<?= $pid ?>"><input type="hidden" name="id" value="<?= (int)$selected['id'] ?>"><input type="hidden" name="version" value="<?= (int)$selected['version'] ?>">
<label>Решение<select name="state"><?php selectOptions($selected['state']==='new'?['reviewing'=>OSS_STATES['reviewing'],'rejected'=>OSS_STATES['rejected']]:array_intersect_key(OSS_STATES,array_flip(['reviewing','accepted','rejected'])),'reviewing') ?></select></label>
<label>ID внутренней задачи (сначала укажите тот же upstream в карточке задачи)<input type="number" min="1" name="task_id" value="<?= h($selected['task_id']??'') ?>"></label><label>Комментарий contributor<textarea name="body" maxlength="4000"></textarea></label><label>Публичная release note (обязательна при принятии)<textarea name="public_note" maxlength="4000"></textarea></label><button class="primary">Сохранить решение</button></form><?php endif ?>
<?php if ($selected['state']==='accepted'): ?><p>Подготовленная публичная запись:</p><p class="criteria-text"><?= h($selected['public_note']) ?></p><?php endif ?>
<h3>Обсуждение (последние 200 сообщений)</h3><?php foreach ($comments as $msg): ?><div class="panel inset"><strong><?= h($msg['author_kind']) ?></strong> · <?= h(gmdate('Y-m-d H:i',(int)$msg['created_at'])) ?> UTC<p class="criteria-text"><?= h($msg['body']) ?></p></div><?php endforeach ?>
<form method="post" class="stack"><?php formFields('oss.comment') ?><input type="hidden" name="project_id" value="<?= $pid ?>"><input type="hidden" name="id" value="<?= (int)$selected['id'] ?>"><label>Сообщение<textarea name="body" maxlength="4000" required></textarea></label><button class="secondary">Ответить</button></form></article><?php endif ?></section>
<section class="panel inset"><h2>Публичные вехи и выпуски</h2><p>Название и описание вводятся отдельно. Срок и состояние копируются из выбранной вехи только при явной публикации. Перед выпуском закройте внутреннюю веху.</p>
<?php foreach ($milestones as $m): ?><details class="editor"><summary><?= h($m['title']) ?> · <?= h(MILESTONE_STATES[$m['state']]) ?><?= $m['tag']?' · '.h($m['tag']):'' ?></summary>
<?php if (!$m['tag']): ?><form method="post" class="formgrid"><?php formFields('oss.milestone') ?><input type="hidden" name="project_id" value="<?= $pid ?>"><input type="hidden" name="milestone_id" value="<?= (int)$m['id'] ?>"><input type="hidden" name="milestone_version" value="<?= (int)$m['version'] ?>"><input type="hidden" name="version" value="<?= (int)($m['public_version']??0) ?>"><label>Публичное название<input name="public_title" required maxlength="180" value="<?= h($m['public_title']??'') ?>"></label><label>Публичное описание<textarea name="description" maxlength="4000" required><?= h($m['description']??'') ?></textarea></label><button class="secondary">Опубликовать / обновить веху</button></form>
<?php if ($m['public_version'] && $m['state']==='closed'): ?><form method="post" class="stack"><?php formFields('oss.release') ?><input type="hidden" name="project_id" value="<?= $pid ?>"><input type="hidden" name="milestone_id" value="<?= (int)$m['id'] ?>"><input type="hidden" name="milestone_version" value="<?= (int)$m['version'] ?>"><label>Тег<input name="tag" maxlength="100" required></label><label>Название выпуска<input name="title" maxlength="180" required></label><label>Release notes<textarea name="notes" maxlength="4000" required></textarea></label><fieldset><legend>Включить принятые вклады (до 100)</legend><?php foreach ($eligible as $e): if ((int)$e['milestone_id']!==(int)$m['id']) continue; ?><label><input type="checkbox" name="contribution_ids[]" value="<?= (int)$e['id'] ?>"> #<?= (int)$e['id'] ?> <?= h($e['public_note']) ?></label><?php endforeach ?></fieldset><button class="primary">Опубликовать неизменяемый выпуск</button></form><?php endif ?>
<?php else: ?><p>Опубликован выпуск <?= h($m['tag']) ?>. История сохранена.</p><?php endif ?></details><?php endforeach ?></section>
<nav aria-label="Страницы OSS"><?php if ($page>1): ?><a href="<?= h(url('oss',['project'=>$pid,'state'=>$state,'n'=>$page-1])) ?>">← Предыдущая</a><?php endif ?> <?php if ($more): ?><a href="<?= h(url('oss',['project'=>$pid,'state'=>$state,'n'=>$page+1])) ?>">Следующая →</a><?php endif ?></nav>
